import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		close = bridge.close;
	},
}));

const originalParentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");

beforeEach(() => {
	vi.resetModules();
	vi.clearAllMocks();
	bridge.listeners.clear();
	bridge.connect.mockResolvedValue(undefined);
	bridge.hostContext = {
		toolInfo: { id: "historical-card", tool: { name: "query_sdk" } },
	};
});

afterEach(() => {
	if (originalParentDescriptor) {
		Object.defineProperty(window, "parent", originalParentDescriptor);
	}
});

it("review: detaches a fresh capability result from an id-only restore", async () => {
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: Object.assign(new EventTarget(), {
			location: { origin: "https://portable-host.example" },
		}),
	});
	bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
		if (name === "restore_lobu_app_result" && args.tool_call_id === "historical-card") {
			return {
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Historical card" },
					view_state: { page: 7 },
				},
			};
		}
		if (name === "restore_lobu_app_result" && args.snapshot_capability === "fresh-token") {
			return {
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Fresh card" },
					view_state: {},
				},
			};
		}
		return { isError: false, structuredContent: { saved: false } };
	});

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data, viewState } = useMcpApp<{ title: string }>();
		return (
			<>
				<span>{data?.title ?? "No result"}</span>
				<span>page:{String(viewState.page)}</span>
			</>
		);
	}
	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);
	expect(await screen.findByText("Historical card")).toBeInTheDocument();
	expect(screen.getByText("page:7")).toBeInTheDocument();

	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({
				structuredContent: { title: "Fresh card" },
				_meta: { "lobu/mcp-app-snapshot-capability": "fresh-token" },
			});
		}
	});

	expect(await screen.findByText("Fresh card")).toBeInTheDocument();
	await waitFor(() => expect(screen.getByText("page:undefined")).toBeInTheDocument());
});

