		function Probe() {
			const { data, setViewState, toolName, viewState } = useMcpApp<{
				title: string;
			}>();
			return (
				<>
					<span>{data?.title}</span>
					<span>{toolName}</span>
					<span>{String(viewState["table.sql.page"])}</span>
					<button
						type="button"
						onClick={() => setViewState("table.sql.page", 2)}
					>
						Next page
					</button>
				</>
			);
		}

		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);

		expect(await screen.findByText("Restored result")).toBeInTheDocument();
